using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.USR.Marcas;namespace GraphApi.Services.USR.Marcas{    public class MarcasService : IMarcasService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public MarcasService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadMarcas>> GetMarcas(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM usr.Marcas (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadMarcas>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetMarcasDynamic(            int? marcaID,            string? marca,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "MarcaID, Marca, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM usr.Marcas (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (marcaID.HasValue)            {                vSql.Append(" AND MarcaID = @MarcaID");                vParameters.Add("MarcaID",marcaID);            }            if (!string.IsNullOrWhiteSpace(marca))            {                vSql.Append(" AND Marca LIKE @Marca");                vParameters.Add("Marca",$"%{marca}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadMarcas> CreateMarcas(clCreateMarcas objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO usr.Marcas                (Marca, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@Marca, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.Marca,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT MarcaID, Marca, bEliminado                FROM usr.Marcas (NOLOCK)                WHERE MarcaID = @MarcaID;";            var vReadParams = new { MarcaID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadMarcas>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el Marca con ID {vNewId}.");            return vCreated;        }        public async Task<clReadMarcas?> UpdateMarcas(clUpdateMarcas objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("MarcaID", objInput.MarcaID);            if (objInput.Marca is not null)            {                vSets.Add("Marca = @Marca");                vParameters.Add("Marca", objInput.Marca);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE usr.Marcas                SET {vSetClause}                WHERE MarcaID = @MarcaID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT MarcaID, Marca, bEliminado                FROM usr.Marcas (NOLOCK)                WHERE MarcaID = @MarcaID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadMarcas>(sSelect, new {  objInput.MarcaID });        }        public async Task<bool> DeleteMarcas(int nMarcasID)        {            const string sSql = @"                DELETE FROM usr.Marcas                WHERE MarcaID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nMarcasID });            return vAffected > 0;        }    }}